function backwardAlphabetScore(s: string): number {
  const back = "zyxwvutsrqponmlkjihgfedcba";
  let total = 0;
  for (let i = 0; i < s.length; i++) total += (back.indexOf(s[i]) + 1) * (i + 1);
  return total;
}

